local config = {
  ui_story_30860401_1_dialog_content = "So you're saying, you found some <color=#FFB400>white flowers</color> on the Colossus?",
  ui_story_30860401_2_dialog_content = "Your white flower, to be specific.",
  ui_story_30860401_3_dialog_content = "I've been waking up early for training these last few days...",
  ui_story_30860401_4_dialog_content = "And I started noticing this odd, flowery smell.",
  ui_story_30860401_5_dialog_content = "Finally, just this morning, I found the source of the smell.",
  ui_story_30860401_6_dialog_content = "Someone had placed these mysterious white flowers in all corners of the Colossus...",
  ui_story_30860401_7_dialog_content = "But there are plenty of people here with flowers.",
  ui_story_30860401_8_dialog_content = "It's true, there are plenty of folks with flowers on the Colossus...",
  ui_story_30860401_X8_dialog_content = "Hiiro, Nikinis, Jola...",
  ui_story_30860401_9_dialog_content = "But you're the only one who has this kind of white flower!",
  ui_story_30860401_10_dialog_content = "You're so certain it's me, huh... What makes you so sure?",
  ui_story_30860401_11_dialog_content = "I have proof!",
  ui_story_30860401_17_dialog_content = "Is this your idea of a joke? First you put flowers on the Lord's head, then you planted them all over Colossus?",
  ui_story_30860401_18_dialog_content = "Nope!",
  ui_story_30860401_19_dialog_content = "Of course not ♩",
  ui_story_30860401_20_dialog_content = "The one who planted them♫ ♩",
  ui_story_30860401_21_dialog_content = "Bows their head in <color=#FFB400>prayer</color>.",
  ui_story_30860401_22_dialog_content = "And offers their <color=#FFB400>condolences</color>!",
  ui_story_30860401_23_dialog_content = "(Prayer? Condolence? Why does it sound like a <color=#FFB400>mortician</color>?!)",
  ui_story_30860401_24_dialog_content = "It's <color=#FFB400>Uriah</color>!",
  ui_story_30860401_25_dialog_content = "You can't fool me!",
  ui_story_30860401_26_dialog_content = "I did some research, and these white flowers are exactly the same as the ones on your flower vines!",
  ui_story_30860401_27_dialog_content = "So you're condemning me for this?",
  ui_story_30860401_28_option_content = "That's not what I meant!",
  ui_story_30860401_29_dialog_content = "I just wanted to ask you about it...",
  ui_story_30860401_30_option_content = "You're not being charged with a crime or anything...",
  ui_story_30860401_31_dialog_content = "I was curious, is all.",
  ui_story_30860401_32_dialog_content = "All those flowers covering the Colossus...",
  ui_story_30860401_33_dialog_content = "It's the first time I've seen someone plant flowers on the Colossus.",
  ui_story_30860401_34_dialog_content = "Since you're so certain it was me, allow me to express my apologies.",
  ui_story_30860401_35_dialog_content = "Even though this really isn't something that needs to be kept hidden.",
  ui_story_30860401_36_dialog_content = "So you are the one who planted these flowers, then?",
  ui_story_30860401_37_dialog_content = "It's just a small part of my prayers. I hope you don't take offense?",
  ui_story_30860401_38_option_content = "I don't mind of course...",
  ui_story_30860401_39_dialog_content = "If anything, it cheers me up seeing so many flowers after training all day.",
  ui_story_30860401_40_option_content = "I'm just worried if it will hurt Soroz...",
  ui_story_30860401_41_dialog_content = "Please put your mind at ease, these flowers don't grow naturally—even their stems are made from my flower vine.",
  ui_story_30860401_42_dialog_content = "I placed them all over Colossus as a sign of my respect.",
  ui_story_30860401_43_dialog_content = "Now that you mention it, your flower vines have those white flowers on them, too. Are they your favorite?",
  ui_story_30860401_44_dialog_content = "It's not that they are my favorite, but...",
  ui_story_30860401_45_dialog_content = "Do you understand the meaning of these flowers?",
  ui_story_30860401_46_option_content = "Not really, no...",
  ui_story_30860401_47_dialog_content = "What do they mean?",
  ui_story_30860401_48_option_content = "Sort of, yeah...",
  ui_story_30860401_49_dialog_content = "So your power has something to do with their meaning?",
  ui_story_30860401_50_dialog_content = "This flower symbolizes \"<color=#FFB400>a tragic farewell</color>.\"",
  ui_story_30860401_51_dialog_content = "So... your power is tied to farewell?",
  ui_story_30860401_52_dialog_content = "Is it related to your family?",
  ui_story_30860401_53_dialog_content = "Yes... and to me, as well.",
  ui_story_30860401_54_dialog_content = "You've been so kind, listening to me all this time. I will keep you in my prayers day and night.",
  ui_story_30860401_55_dialog_content = "I can't tell if you're serious or not sometimes.",
  ui_story_30860401_56_dialog_content = "Ahem, anyway... As Navigator, it's my duty to understand my crew as much as possible, don't you agree?",
  ui_story_30860401_57_dialog_content = "If you truly wish to know, I would be more than happy to tell you about my past.",
  ui_story_30860401_58_dialog_content = "But in exchange, will you tell me about the things that you mourn for?",
  ui_story_30860401_59_dialog_content = "Me? What does this have to do with me?",
  ui_story_30860401_60_dialog_content = "Your family, for instance. The things you want to protect... The things you had to say farewell to...",
  ui_story_30860401_61_dialog_content = "That's all ancient history... Besides, I don't remember much about my family.",
  ui_story_30860401_62_dialog_content = "Anything will do. Please?",
  ui_story_30860401_63_dialog_content = "Hmm... Well, I'm sure you've heard that I was raised by Soroz all my life, right?",
  ui_story_30860401_64_dialog_content = "Ah yes, the amazing White Colossus.",
  ui_story_30860401_65_dialog_content = "For 17 years, I grew up here. At first, I didn't understand anything about the outside world.",
  ui_story_30860401_66_dialog_content = "All the images in my mind were mostly fragments of memories I got from Soroz...",
  ui_story_30860401_67_dialog_content = "Like how I was hidden in this Colossus...",
  ui_story_30860401_68_dialog_content = "And how my people died fighting off the Eclipsites... to protect me.",
  ui_story_30860401_69_dialog_content = "But again, these memories were all planted in my brain. I have no way to confirm if they're real or not...",
  ui_story_30860401_70_dialog_content = "I learned of this, as well.",
  ui_story_30860401_71_dialog_content = "As well as something you don't know about.",
  ui_story_30860401_72_dialog_content = "Something... I don't know about?",
  ui_story_30860401_73_dialog_content = "Do you remember the <color=#FFB400>red mark on Colossus' wing</color>?",
  ui_story_30860401_74_option_content = "Yeah, I remember...",
  ui_story_30860401_75_dialog_content = "When I was cleaning Colossus once, Vice gave me a hard time because of how shabby Soroz looked. It made her really upset for some time.",
  ui_story_30860401_76_option_content = "I don't recall...",
  ui_story_30860401_77_dialog_content = "But a long time ago, there was this mark on the Colossus that I couldn't wipe clean no matter how hard I tried.",
  ui_story_30860401_78_dialog_content = "Those marks tell a story. They aren't just grime on a machine.",
  ui_story_30860401_79_dialog_content = "So what was it?",
  ui_story_30860401_80_dialog_content = "In all those fragmented memories... are you sure you haven't seen it before?",
  ui_story_30860401_81_dialog_content = "Wait, could it be...",
  ui_story_30860401_82_dialog_content = "Precisely. That was no ordinary stain, but the <color=#FFB400>blood</color> of your fellow Caelestite.",
  ui_story_30860401_83_dialog_content = "Soroz has never forgotten them. It's a symbol of its history with you as you grew up.",
  ui_story_30860401_84_dialog_content = "How did you find out about this, Uriah?",
  ui_story_30860401_85_dialog_content = "When I first arrived on the Colossus, I stumbled upon this <color=#FFB400>diary</color>...",
  ui_story_30860401_86_dialog_content = "It likely belongs to a person who is no longer with us... Its pages are full of stories of you and your people.",
  ui_story_30860401_87_dialog_content = "Please forgive me, it was wrong of me to read it.",
  ui_story_30860401_88_dialog_content = "I had no idea when I found it, and I have been waiting for the chance to pass it to you.",
  ui_story_30860401_89_dialog_content = "I've prayed for this moment for so long...",
  ui_story_30860401_90_dialog_content = "And now, I believe it is the right time to return it to you.",
  ui_story_30860401_91_dialog_content = "This diary, and these flowers... Please accept them.",
  ui_story_30860401_92_dialog_content = "I hope that you can mourn and pray for your fallen people, and bid them a proper farewell.",
  ui_story_30860401_93_dialog_content = "*Take white flowers*",
  ui_story_30860401_94_dialog_content = "According to that diary, today happens to be the day of mourning for the departed...",
  ui_story_30860401_95_dialog_content = "A proper farewell, huh... This is the first time I've heard of such a holiday.",
  ui_story_30860401_96_dialog_content = "I should do something special in remembrance... Thank you.",
  ui_story_30860401_97_dialog_content = "Just like everyone else, I keep you in my prayers, as well.",
  ui_story_30860401_98_dialog_content = "Say... Why do I feel like I'm forgetting something?",
  ui_story_30860401_99_dialog_content = "Are you?",
  ui_story_30860401_100_dialog_content = "Am I... not?",
  ui_story_30860401_101_dialog_content = "I don't believe you are. You should get some rest. I'll pray for you tonight before I go to bed.",
  ui_story_30860401_X101_dialog_content = "Until next time.",
  ui_story_30860401_102_dialog_content = "Wait, I remember now! You're supposed to tell me about your past...",
  ui_story_30860401_103_dialog_content = "Where'd she go?!",
  ui_story_30860401_104_dialog_content = "Uriah!!",
  ui_story_30860601_1_dialog_content = "Can you hear those <color=#FFB400>sounds</color>?",
  ui_story_30860601_2_dialog_content = "Sounds?",
  ui_story_30860601_3_dialog_content = "The waves rolling on the shore, the seagulls calling out as they play.",
  ui_story_30860601_4_dialog_content = "The long leaves of the palm trees swaying in the wind, and the sound of feet walking across the sands.",
  ui_story_30860601_5_dialog_content = "All of these sounds are absolutely brimming with the vibrant energy of summer! Ah, it's so comforting...",
  ui_story_30860601_6_dialog_content = "Listen closely.",
  ui_story_30860601_7_dialog_content = "Wow, you're right! When I pay attention, there are so many sounds all around us!",
  ui_story_30860601_8_dialog_content = "Yes.",
  ui_story_30860601_9_dialog_content = "(You don't see this look on Uriah's face every day.)",
  ui_story_30860601_10_dialog_content = "(Normally, she looks so dignified and elegant, and all wrapped up from head to foot... like a sculpture, or something.)",
  ui_story_30860601_11_dialog_content = "(But it looks like not even that serious expression of hers can hold up at the beach.)",
  ui_story_30860601_12_dialog_content = "I know what you are thinking, that you seldom see me like this.",
  ui_story_30860601_13_dialog_content = "But these clothes are perfect for warding off the summer heat.",
  ui_story_30860601_14_dialog_content = "Do you think they suit me?",
  ui_story_30860601_15_option_content = "Absolutely!",
  ui_story_30860601_16_dialog_content = "Even though they're designed for swimming, they still have the Lumopolis elegant style and quality.",
  ui_story_30860601_17_dialog_content = "When you wear them, it gives everyone an impression of grace and piety! Like a pearl from the sea!",
  ui_story_30860601_18_dialog_content = "I'm... not sure if I'm making sense or not.",
  ui_story_30860601_19_dialog_content = "I never expected to receive such sincere praise from you. You have my gratitude.",
  ui_story_30860601_20_dialog_content = "To be honest, when we arrived at the beach, I thought you would still wear your nun's attire.",
  ui_story_30860601_21_option_content = "It's a little surprising.",
  ui_story_30860601_22_dialog_content = "These clothes are really different from what you usually wear.",
  ui_story_30860601_23_dialog_content = "In my mind, you're always wearing your nun's attire.",
  ui_story_30860601_24_dialog_content = "I must dress solemnly when in prayer.",
  ui_story_30860601_25_dialog_content = "I take meticulous care of my clothing, just as I care for my white flowers.",
  ui_story_30860601_26_dialog_content = "This is a sign of respect for the injured, the dearly departed, and their loved ones whom they have left behind.",
  ui_story_30860601_27_dialog_content = "I believe no one wishes to see someone dressed casually as they lead them through life's difficulties. Am I correct?",
  ui_story_30860601_28_dialog_content = "However, I am off duty right now.",
  ui_story_30860601_29_dialog_content = "Why did you decide to come to the Ocean Sovereign?",
  ui_story_30860601_30_dialog_content = "I have come at Lady Carleen's invitation.",
  ui_story_30860601_31_dialog_content = "She is a kind and considerate girl. She worries that I work too much and wishes for me to enjoy myself more.",
  ui_story_30860601_32_dialog_content = "I could never refuse an invitation as gracious and considerate as this.",
  ui_story_30860601_33_dialog_content = "Also... I have known about the Ocean Sovereign for quite some time, and I have always wanted to see it for myself.",
  ui_story_30860601_34_dialog_content = "I believe I may even discover <color=#FFB400>the sound I am looking for</color>.",
  ui_story_30860601_35_dialog_content = "Do you know about the Ocean Sovereign, PlayerName?",
  ui_story_30860601_36_dialog_content = "Bonacie told me about it before. The Ocean Sovereign is a ceremony left behind by the Aurorians that used to live on this beach.",
  ui_story_30860601_37_dialog_content = "It's a competition that tests the participants' <color=#FFB400>strength</color>, <color=#FFB400>knowledge</color>, and <color=#FFB400>bravery</color>, in order to determine a winner.",
  ui_story_30860601_38_dialog_content = "The festival is supposed to bless this place with good weather.",
  ui_story_30860601_39_dialog_content = "You are absolutely correct, but do you know why the Ocean Sovereign is a test of those three qualities?",
  ui_story_30860601_40_dialog_content = "Huh? There's a story behind it?",
  ui_story_30860601_41_dialog_content = "\"The sounds carry the stories of the past.\"",
  ui_story_30860601_42_dialog_content = "Long ago, the people of this coast depended on the gifts of the sky and the sea to live.",
  ui_story_30860601_43_dialog_content = "Over time, they came to take these gifts for granted.",
  ui_story_30860601_44_dialog_content = "Then one day, the sky no longer brought rain, the sea receded, and everything that lived in the waters died as a result.",
  ui_story_30860601_45_dialog_content = "In the distance, a towering castle arose from the depths of the sea, and dark clouds soon blanketed the entire Celestial Coast.",
  ui_story_30860601_46_dialog_content = "Only by completing the trials of the three goddesses of Strength, Knowledge, and Bravery would the coast return to its original state.",
  ui_story_30860601_47_dialog_content = "Usually, this is where a hero appears to save the day!",
  ui_story_30860601_48_dialog_content = "Precisely.",
  ui_story_30860601_49_dialog_content = "To save the coastline, a <color=#FFB400>king</color> at the time resolutely stepped forward.",
  ui_story_30860601_50_dialog_content = "Using his unwavering strength, he scaled the castle.",
  ui_story_30860601_51_dialog_content = "With his clever mind, he bested the Goddess of Knowledge at her own game.",
  ui_story_30860601_52_dialog_content = "And finally, with his noble courage, he overcame his greatest fears and passed the trial of the Goddess of Bravery.",
  ui_story_30860601_53_dialog_content = "In the end, the king gained the favor of all three goddesses.",
  ui_story_30860601_54_dialog_content = "After receiving their blessing, rain began to pour from the sky once more, and the sea surged back up the coastline, bringing life with it.",
  ui_story_30860601_55_dialog_content = "The goddesses used their power to return the king to his own kingdom.",
  ui_story_30860601_56_dialog_content = "However, the world is ever-changing, and it was no longer the same as it had been during his reign.",
  ui_story_30860601_57_dialog_content = "A hundred years had passed, families and friends alike had long since left the world.",
  ui_story_30860601_58_dialog_content = "In his grief, the king turned himself into a stone atop a cliff, where he may always protect the future of his kingdom.",
  ui_story_30860601_59_dialog_content = "Though his loved ones were no longer with him, the words of his deeds survived the passage of time. In honor of the king and the three goddesses, the Ocean Sovereign came to be.",
  ui_story_30860601_60_dialog_content = "To the local populace, strength, knowledge, and bravery are presumably the three most admirable qualities in a person.",
  ui_story_30860601_61_dialog_content = "It sounds just like a fairy tale.",
  ui_story_30860601_62_dialog_content = "Are you implying that the story does not sound real to you?",
  ui_story_30860601_X62_dialog_content = "Maybe a little...",
  ui_story_30860601_63_dialog_content = "Even though the story sounds kind of made-up, the Ocean Sovereign is very much a real thing.",
  ui_story_30860601_64_dialog_content = "So are the trials of strength, knowledge, and bravery.",
  ui_story_30860601_65_dialog_content = "(Although the \"trials\" are just volleyball, chess, and singing contests...)",
  ui_story_30860601_66_dialog_content = "What do you think about the story, Uriah?",
  ui_story_30860601_67_dialog_content = "What do I think about it? Well...",
  ui_story_30860601_68_dialog_content = "Come on, there's nothing special here.",
  ui_story_30860601_69_dialog_content = "What's all the commotion over there?",
  ui_story_30860601_70_dialog_content = "I told you, this kind of event is only good for cheating tourists out of their money.",
  ui_story_30860601_71_dialog_content = "They make a big deal about some subject, then host a bunch of pointless events to drum up business.",
  ui_story_30860601_72_dialog_content = "After that, they set up stalls all over the place to capitalize on the situation. Shaved ice, cold drinks, swimwear, beach products...",
  ui_story_30860601_73_dialog_content = "In the end, the whole point of these things is to make us pull out our wallets and shell out.",
  ui_story_30860601_74_dialog_content = "I mean, no one actually believes in this \"Ocean Sovereign\" legend crap, right? Or these nonsenses about strength, bravery, and knowledge...",
  ui_story_30860601_75_dialog_content = "(I can't help but think he has a point...)",
  ui_story_30860601_76_dialog_content = "That's enough.",
  ui_story_30860601_77_dialog_content = "...",
  ui_story_30860601_78_dialog_content = "Are you alright, Uriah?",
  ui_story_30860601_79_dialog_content = "Yes. What he said is indeed correct.",
  ui_story_30860601_80_dialog_content = "No matter what we say or think, legends like this are bound to disappear eventually, leaving only semblances of what they once meant.",
  ui_story_30860601_81_dialog_content = "The Ocean Sovereign, the stone king, the castle in the sea—they all exist in people's imaginations, and will change and fade with time.",
  ui_story_30860601_82_dialog_content = "What a pity... This is definitely not the sound I was hoping to hear.",
  ui_story_30860601_83_dialog_content = "Uriah!",
  ui_story_30860601_84_dialog_content = "Yes?",
  ui_story_30860601_85_dialog_content = "I... I'm willing to believe in the story!",
  ui_story_30860601_86_dialog_content = "PlayerName?",
  ui_story_30860601_87_dialog_content = "Because... <size=45>I think it's really romantic!</size>",
  ui_story_30860601_88_dialog_content = "To protect his homeland, the king went through so many hardships... He proved that his strength, knowledge, and bravery were all real!",
  ui_story_30860601_89_dialog_content = "And even though his trials changed the course of his life, he had no regrets, and even turned himself into a stone to continue protecting this coast...",
  ui_story_30860601_90_dialog_content = "If the Ocean Sovereign came from this kind of story, it HAS to be meaningful!",
  ui_story_30860601_91_dialog_content = "Hmm... So this is how you feel, PlayerName.",
  ui_story_30860601_92_dialog_content = "(It looks like Uriah is deep in thought. Did I say something I shouldn't have?)",
  ui_story_30860601_93_dialog_content = "Do not be so nervous, PlayerName. The sound of your voice speaking your mind is both powerful and persuasive.",
  ui_story_30860601_94_dialog_content = "Also, I believe you have a very sound interpretation of the story. This is the kind of sound I like to hear.",
  ui_story_30860601_95_dialog_content = "Do you know that conches can retain sounds, as well?",
  ui_story_30860601_96_dialog_content = "A conch will store beautiful echoes deep in its spiral. When we ask it a question, it will respond right away.",
  ui_story_30860601_97_dialog_content = "I want to preserve the sound of your voice, so please... speak the words you just spoke to me into this conch!",
  ui_story_30860601_98_dialog_content = "Into the conch...?",
  ui_story_30860601_99_dialog_content = "(Why is everyone watching?! I feel so awkward all of a sudden...)",
  ui_story_30860601_100_dialog_content = "(But if it's for Uriah... I'll do it!!!)",
  ui_story_30860601_101_dialog_content = "<size=45>I think the story of the Ocean Sovereign is super romantic!</size>",
  ui_story_30860601_102_dialog_content = "Huh, didn't think there were people this gullible in the world.",
  ui_story_30860601_103_dialog_content = "Come on, let's go...",
  ui_story_30860601_104_dialog_content = "Yeah, sure...",
  ui_story_30860601_105_dialog_content = "(But I think the story of the Ocean Sovereign is super romantic, too...)",
  ui_story_30860601_106_dialog_content = "Thank you, PlayerName.",
  ui_story_30860601_107_dialog_content = "I was surprised to see this side of you, as well. Surprised, but happy.",
  ui_story_30860601_108_dialog_content = "To be honest, I know these stories are not necessarily true.",
  ui_story_30860601_109_dialog_content = "But I face true pain and suffering almost every day, so I have come to cherish the small joy that fictional tales like this can bring.",
  ui_story_30860601_110_dialog_content = "Well, if you're happy, I'm glad too!",
  ui_story_30860601_111_dialog_content = "How could I be unhappy when you are here?",
  ui_story_30860601_112_dialog_content = "The true meaning of holidays and festivals lies in what they can pass down from generation to generation.",
  ui_story_30860601_113_dialog_content = "To us, their value lies in <color=#FFB400>what we believe in</color>.",
  ui_story_30860601_114_dialog_content = "I have already found credence in something worthwhile.",
  ui_story_30860601_115_dialog_content = "And that \"something\" is our choice to believe in those <color=#FFB400>kind and honest qualities</color>.",
  ui_story_30860601_116_dialog_content = "Strength, knowledge, and bravery.",
  ui_story_30860601_117_dialog_content = "In conclusion, I believe that a little romanticism can lead to a longer, happier life.",
  ui_story_30860601_118_dialog_content = "I also believe that someone like you will live a life of happiness, no matter what hardships may come your way.",
  ui_story_30860601_119_dialog_content = "Let us end our stroll here for today. We ought to go back and rest for a while.",
  ui_story_30860601_120_dialog_content = "Sure! Let's make our way back, then.",
  ui_story_30860601_121_dialog_content = "Oh, and one more thing.",
  ui_story_30860601_122_dialog_content = "<color=#e8d9bb>Uriah picks up the conch and whispers something into it.</color>",
  ui_story_30860601_123_dialog_content = "Uriah?",
  ui_story_30860601_124_dialog_content = "I was simply recording what I most wanted to say just now.",
  ui_story_30860601_125_dialog_content = "But it is a secret. Maybe someday, you will be able to hear it from inside this conch.",
  ui_story_30860601_126_dialog_content = "\"Thank you, PlayerName. This is the sound I wanted to hear the most today.\""
}
return config
